use boa_engine::{Context, JsValue};
use futures_lite::future;
use std::cell::RefCell;
use std::pin::pin;
use std::rc::Rc;

#[test]
fn continuously_yielding_keeps_loop_pending_and_runs_generic() {
    let executor = Rc::new(SimpleJobExecutor::new());
    let mut context = Context::builder()
        .job_executor(executor)
        .build()
        .unwrap();

    // Enqueue an infinitely-yielding async job.
    let async_job = NativeAsyncJob::new(|_ctx: &RefCell<&mut Context>| async {
        loop {
            future::yield_now().await;
        }
        #[allow(unreachable_code)]
        Ok(JsValue::undefined())
    });
    let exec = context
        .downcast_job_executor::<SimpleJobExecutor>()
        .unwrap();
    exec.clone().enqueue_job(Job::AsyncJob(async_job), &mut context);

    let flag = Rc::new(RefCell::new(false));

    future::block_on(async {
        let ctx_cell = RefCell::new(&mut context);
        let fut = exec.clone().run_jobs_async(&ctx_cell);
        let mut fut = pin!(fut);

        // First poll: async future is running -> pending.
        assert_eq!(future::poll_once(fut.as_mut()).await, None);

        // Enqueue a generic job between polls.
        let realm = ctx_cell.borrow().realm().clone();
        let flag2 = flag.clone();
        let generic = GenericJob::new(
            move |_ctx: &mut Context| {
                *flag2.borrow_mut() = true;
                Ok(JsValue::undefined())
            },
            realm,
        );
        exec.clone()
            .enqueue_job(Job::GenericJob(generic), &mut ctx_cell.borrow_mut());

        // Second poll: still pending (async loop), but generic job must have run.
        assert_eq!(future::poll_once(fut.as_mut()).await, None);
        assert!(*flag.borrow(), "generic job enqueued between polls must run");
    });
}

#[test]
fn empty_loop_resolves() {
    let executor = Rc::new(SimpleJobExecutor::new());
    let mut context = Context::builder()
        .job_executor(executor)
        .build()
        .unwrap();
    let exec = context
        .downcast_job_executor::<SimpleJobExecutor>()
        .unwrap();

    future::block_on(async {
        let ctx_cell = RefCell::new(&mut context);
        let fut = exec.run_jobs_async(&ctx_cell);
        let mut fut = pin!(fut);
        // All queues empty, no async futures -> resolves.
        assert!(matches!(future::poll_once(fut.as_mut()).await, Some(Ok(()))));
    });
}
